      "translation": "framstilling • skildring • avbilding",
      "explanation": [
        "Hovudtanke: die Darstellung er eit substantiv i hokjønn, danna av verbet darstellen. Det tyder ei framstilling eller avbilding av noko: det eit menneske seier, skriv, teiknar eller spelar.",
        "Fleirtal er die Darstellungen. Tydingar: framstilling (skildring av hendingar med ord), avbilding (i ei teikning, eit diagram: grafische Darstellung), tolking (ein skodespelar si tolking av ei rolle).",
        "Vanlege samband: eine Darstellung geben (gje ei framstilling), die Darstellung der Ereignisse, die grafische Darstellung (grafisk framstilling)."
      ],
      "examples": [
        {
          "de": "Die Darstellung des Unfalls war sehr genau.",
          "lv": "Framstillinga av ulukka var svært nøyaktig."
        },
        {
          "de": "Die Zeitung gibt eine einseitige Darstellung der Ereignisse.",
          "lv": "Avisa gjev ei einsidig framstilling av hendingane."
        },
        {
          "de": "Die Darstellung des Hamlet durch den jungen Schauspieler war beeindruckend.",
          "lv": "Den unge skodespelaren si tolking av Hamlet var imponerande."
        },
        {
          "de": "Die grafische Darstellung zeigt die Entwicklung der Preise.",
          "lv": "Den grafiske framstillinga viser prisutviklinga."
        }
      ],
      "comparison": [
        {
          "word": "die Beschreibung",
          "meaning": "skildring, omtale",
          "example": "Die Beschreibung ist genau. – Skildringa er nøyaktig."
        },
        {
          "word": "der Bericht",
          "meaning": "rapport, forteljing",
          "example": "Der Bericht ist kurz. – Rapporten er kort."
        },
        {
          "word": "die Schilderung",
          "meaning": "levande skildring",
          "example": "Seine Schilderung war lebendig. – Skildringa hans var levande."
        }
      ],
      "tip": [
        "Etter Darstellung følgjer ofte von eller genitiv: die Darstellung des Problems, die Darstellung von Daten.",
        "Om eit diagram eller ein figur seier ein grafische Darstellung."
      ],
      "important": [
        "Darstellung er ikkje det same som Beschreibung: Beschreibung er ei skildring med ord, medan Darstellung òg kan vere ei teikning, eit diagram eller ei rolletolking.",
        "Die Darstellung er hokjønn, i fleirtal die Darstellungen."
      ],
