        "Skiljeleg verb: er weist zu, wies zu, hat zugewiesen. Vanlegvis med dativ (kven?) og akkusativ (kva?): jemandem etwas zuweisen. Passiv er òg vanleg: Mir wurde ein Platz zugewiesen.",
