        "Svakt verb: er fordert, forderte, hat gefordert. Det ein krev, står i akkusativ, og den ein krev av, blir vist med von + dativ: etwas von jemandem fordern. Det kan òg følgje ei dass-setning. I overført tyding kan fordern tyde å krevje offer: Der Unfall forderte zwei Todesopfer.",
        "Pass på det nærskylde ordet: fordern (krevje) og fördern (fremje) skil seg berre ved omlyden."
